// fp8e4m3fn -> fp32 (inverse; for tests). bias 7, max 448, NaN at 0x7F/0xFF,
// subnormal mant*2^-6. Mirrors the OCP e4m3fn spec (NOT fnuz: bias 7, max 448).
inline float fp8e4m3fn_to_f32(uint8_t b) {
