               key, slot_score, tail_k_ref, tail_score_ref,
               ape, block_tables, req_pool_indices, positions, seq_lens,
               out_cache_loc, rout);
    float maxd = 0.0f;
    for (size_t i = 0; i < out.size(); ++i)
