                     + (size_t)slot_in_page * head_dim;
    float* scale_dst = reinterpret_cast<float*>(
        cache_u8 + (size_t)page * page_bytes) + scale_off_f32 + slot_in_page;
    store_kpool_fp8(acc.data(), denom.data(), head_dim, round_scale, k_dst,
