    18	constexpr float kNegInf = -std::numeric_limits<float>::infinity();
    19	
    20	// Normalized 128-point Hadamard (1/sqrt(128)), the exact stage decomposition
    21	// sglang's kpool_fp8_index.py::_hadamard128 uses (involutory up to fp32
    22	// rounding -- verified offline). Applied to a single 128-vector (the per-pool
    23	// weighted mean), so this is the 1-D form mirroring the Triton kernel's
    24	// reshape(64,2,1)->...->reshape(128) ladder. ``head_dim`` MUST be 128 (the
    25	// GLM-5.3 / DeepSeek-V3 ``index_head_dim``); the loop is fully unrolled and
    26	// bounded so a larger head_dim is a logic error caught up front.
    27	inline void hadamard128(float* x) {
    28	  struct Stage { int groups; int stride; };
    29	  constexpr Stage kStages[] = {{64, 1}, {32, 2}, {16, 4}, {8, 8},
    30	                               {4, 16}, {2, 32}, {1, 64}};
    31	  for (const Stage st : kStages) {
    32	    const int G = st.groups;
    33	    const int S = st.stride;
    34	    const int two_s = 2 * S;
    35	    float tmp[128];
    36	    for (int g = 0; g < G; ++g) {
    37	      const int base = g * two_s;
    38	      for (int k = 0; k < 2; ++k)
    39	        for (int s = 0; s < S; ++s) {
    40	          const float a = x[base + s];
    41	          const float b = x[base + S + s];
    42	          tmp[base + k * S + s] = (k == 0) ? (a + b) : (a - b);
    43	        }
    44	    }
    45	    for (int i = 0; i < 128; ++i) x[i] = tmp[i];
    46	  }
    47	  constexpr float kScale = 0.08838834764831845f;  // 1/sqrt(128)
    48	  for (int i = 0; i < 128; ++i) x[i] *= kScale;
    49	}
    50	
    51	// Online (FlashAttention-style) softmax: maintain running max, weight-sum
    52	// denominator and weighted accumulator across ``pool_size`` slots, then
    53	// write the mean (acc/denom) + its Hadamard transform. ``scores``/``keys``
    54	// are [pool_size, head_dim] fp32.
    55	inline void compress_pool(const float* scores, const float* keys,
    56	                          int pool_size, int head_dim, float* out_vec) {
    57	  // head_dim is 128; accumulate the full vector to bound the register traffic
    58	  // on the host (the device kernel lanes it across a wavefront).
    59	  std::vector<float> m(head_dim, kNegInf);
    60	  std::vector<float> acc(head_dim, 0.0f);
    61	  std::vector<float> denom(head_dim, 0.0f);
    62	  for (int slot = 0; slot < pool_size; ++slot) {
    63	    const float* s = scores + slot * head_dim;
    64	    const float* k = keys + slot * head_dim;
    65	    for (int d = 0; d < head_dim; ++d) {
    66	      const float score = s[d];
    67	      const float new_m = std::max(m[d], score);
    68	      const float rescale = std::exp(m[d] - new_m);
    69	      const float prob = std::exp(score - new_m);
    70	      denom[d] = denom[d] * rescale + prob;
    71	      acc[d] = acc[d] * rescale + k[d] * prob;
    72	      m[d] = new_m;
    73	    }
    74	  }
    75	  for (int d = 0; d < head_dim; ++d) out_vec[d] = acc[d] / denom[d];
    76	  if (head_dim == 128) hadamard128(out_vec);
    77	}
