    const std::vector<float>& ape, int n_reqs, int r,
    std::vector<float>& acc, std::vector<float>& denom) {
  (void)batch;
  const int req_raw = req_raw_of(r);  // replaced below -- see note
  (void)req_raw;
  return false;
}

}  // namespace dsa_kpool_ref

