}

// Full DECODE reference: per-row accumulate + mean + dense Hadamard + fp32
// write, plus the unconditional in-place live-tail write. Mirrors
// dsa_kpool_decode_update_cpu exactly.
inline void decode_ref(int batch, int pool_size, int head_dim,
                       int tail_size, int slots_per_page, int block_table_cols,
                       int n_reqs, const std::vector<float>& key,
                       const std::vector<float>& slot_score,
                       std::vector<float>& tail_k,
                       std::vector<float>& tail_score,
                       const std::vector<float>& ape,
                       const std::vector<int32_t>& block_tables,
                       const std::vector<int32_t>& req_pool_indices,
                       const std::vector<int32_t>& positions,
                       const std::vector<int32_t>& seq_lens,
                       const std::vector<int32_t>& out_cache_loc,
                       std::vector<float>& out) {
  std::vector<float> acc, denom, mean(head_dim), h(128);
  for (int r = 0; r < batch; ++r) {
    const bool complete = decode_row_accumulate(
        pool_size, head_dim, tail_size, key, slot_score, tail_k, tail_score,
        ape, n_reqs, r, req_pool_indices, positions, seq_lens, out_cache_loc,
        acc, denom);
    if (complete) {
      for (int d = 0; d < head_dim; ++d) mean[d] = acc[d] / denom[d];
      apply_dense_hadamard(mean, h);
      const int safe_pos = std::max(positions[r], 0);
      const int pool_id = safe_pos / pool_size;
      const int pool_page_group = pool_id / slots_per_page;
      int tpr = std::min(std::max(pool_page_group * pool_size, 0), block_table_cols - 1);
      const int packed_page = block_tables[(size_t)r * block_table_cols + tpr];
      const int loc_slot = pool_id % slots_per_page;
      float* dst = out.data() + (size_t)packed_page * slots_per_page * head_dim
                             + (size_t)loc_slot * head_dim;
      for (int d = 0; d < head_dim; ++d) dst[d] = h[d];
    }
    // Unconditional live-tail write (no-op when !pos_valid).
    const int req_raw = req_pool_indices[r];
    const bool req_valid = req_raw >= 0 && req_raw < n_reqs;
    const int req = req_valid ? req_raw : std::min(std::max(req_raw, 0), n_reqs - 1);
    const int pos_raw = positions[r];
    const int safe_pos = std::max(pos_raw, 0);
    const bool pos_valid = req_valid && out_cache_loc[r] != 0 &&
                           pos_raw >= 0 && pos_raw < seq_lens[r];
    if (pos_valid) {
      const int phys_slot = ((safe_pos % tail_size) + tail_size) % tail_size;
      float* tk = tail_k.data() + (size_t)req * tail_size * head_dim
                                 + (size_t)phys_slot * head_dim;
      float* ts = tail_score.data() + (size_t)req * tail_size * head_dim
                                     + (size_t)phys_slot * head_dim;
      for (int d = 0; d < head_dim; ++d) {
        tk[d] = key[(size_t)r * head_dim + d];
        ts[d] = slot_score[(size_t)r * head_dim + d];
      }
    }
  }
}

// ---------------------------------------------------------------------------
// fp8e4m3fn encoder + legacy-cache store (shared by the fp8 tests).
// frexp-based, independent of the impl's bit packing.
// ---------------------------------------------------------------------------

// float -> bf16 (round-to-nearest-even on the top 16 bits), then back to
// float. Used by the fp8 reference: the impl pools in bf16 before the fp8
// store, so the oracle reproduces that quantization before encoding.
inline float ref_round_bf16(float v) {
  uint32_t u;
  std::memcpy(&u, &v, 4);
  uint32_t lsb = (u >> 16) & 1;
  u += 0x7fff + lsb;
  std::memcpy(&v, &u, 4);
  return v;
}

// float -> fp8e4m3fn byte, saturating, round-to-nearest-even.
// Modeled independently of the impl: frexp to isolate the exponent, a
// hand-written table for the 8 mantissa codes, and an explicit RNE fixup
// when the remainder ties. NaN -> 0x7f; Inf -> 0x78 (saturate).
inline uint8_t ref_f32_to_fp8e4m3fn(float v) {
  if (std::isnan(v)) return 0x7f;
  if (std::isinf(v)) return 0x78;  // saturate to max normal
  if (v == 0.0f) return 0x00;
  const bool neg = std::signbit(v);
  float a = std::fabs(v);
  if (a > 448.0f) return neg ? 0xf8 : 0x78;
  int e;
  std::frexp(a, &e);  // a = m * 2^e, m in [0.5, 1)
  // fp8 normal exponent range: 2^-6 .. 2^8 (bias 7). Subnormals below.
  float scaled;
  int exp_bits;
  if (e - 1 >= -6) {
    exp_bits = e - 1 + 7;
    scaled = a / std::ldexp(1.0f, e - 1);  // in [1, 2)
  } else {
    exp_bits = 0;
    scaled = a / std::ldexp(1.0f, -6);  // in [0, 1): subnormal
  }
  float m = scaled * 8.0f;  // 3 mantissa bits
  // RNE: round m to nearest int, ties to even.
  float rf = std::floor(m);
  float frac = m - rf;
  int mi = (int)rf;
  if (frac > 0.5f) mi += 1;
  else if (frac == 0.5f) mi += (mi & 1);
  if (mi == 16) {  // mantissa overflow -> bump exponent
    if (exp_bits == 0) { exp_bits = 1; mi = 8; }
    else if (exp_bits == 15) return neg ? 0xf8 : 0x78;
    else { exp_bits += 1; mi = 8; }
    // re-check saturation at the new exponent
    if (exp_bits == 15 && mi == 16) return neg ? 0xf8 : 0x78;
  }
  if (exp_bits > 15) return neg ? 0xf8 : 0x78;
  return (uint8_t)((neg ? 0x80 : 0x00) | (exp_bits << 3) | mi);
}

// Legacy-cache store: ``mean`` (the bf16-rounded pooled vector) at cache
// slot [page, sip] -- fp8 K bytes then the fp32 scale. Mirrors the fp8
// epilogue layout (K region then trailing scales).
inline void ref_store_fp8(const std::vector<float>& mean, int head_dim,
                          int slots_per_page, std::vector<uint8_t>& cache_u8,
                          int page, int sip, bool round_scale) {
  const int page_bytes = slots_per_page * (head_dim + 4);
  uint8_t* k_dst = cache_u8.data() + (size_t)page * page_bytes
                 + (size_t)sip * head_dim;
  float* scale_dst = reinterpret_cast<float*>(
      cache_u8.data() + (size_t)page * page_bytes)
      + (slots_per_page * head_dim / 4) + sip;
  float amax = 0.0f;
  for (int d = 0; d < head_dim; ++d)
    amax = std::max(amax, std::fabs(mean[d]));
  const float y = round_scale ? std::exp2f(std::floor(std::log2f(amax / 448.0f)))
                              : amax / 448.0f;
  const float s_inv = (amax > 0.0f) ? 1.0f / y : 0.0f;
  for (int d = 0; d < head_dim; ++d) {
    const float q = mean[d] * s_inv;
    k_dst[d] = (amax > 0.0f) ? ref_f32_to_fp8e4m3fn(q) : 0;
  }
  std::memcpy(scale_dst, &y, 4);
}

