// ---------------------------------------------------------------------------
// fp8e4m3fn encoder + legacy-cache store (shared by the fp8 tests).
// frexp-based, independent of the impl's bit packing.
// ---------------------------------------------------------------------------

// float -> bf16 (round-to-nearest-even on the top 16 bits), then back to
// float. Used by the fp8 reference: the impl pools in bf16 before the fp8
// store, so the oracle reproduces that quantization before encoding.
inline float ref_round_bf16(float v) {
  uint32_t u;
  std::memcpy(&u, &v, 4);
  uint32_t lsb = (u >> 16) & 1;
  u += 0x7fff + lsb;
  std::memcpy(&v, &u, 4);
  return v;
}

// float -> fp8e4m3fn byte, saturating, round-to-nearest-even.
// Modeled independently of the impl: frexp to isolate the exponent, a
// hand-written table for the 8 mantissa codes, and an explicit RNE fixup
// when the remainder ties. NaN -> 0x7f; Inf -> 0x78 (saturate).
inline uint8_t ref_f32_to_fp8e4m3fn(float v) {
  if (std::isnan(v)) return 0x7f;
  if (std::isinf(v)) return 0x78;  // saturate to max normal
  if (v == 0.0f) return 0x00;
  const bool neg = std::signbit(v);
  float a = std::fabs(v);
  if (a > 448.0f) return neg ? 0xf8 : 0x78;
  int e;
  std::frexp(a, &e);  // a = m * 2^e, m in [0.5, 1)
  // fp8 normal exponent range: 2^-6 .. 2^8 (bias 7). Subnormals below.
  float scaled;
  int exp_bits;
  if (e - 1 >= -6) {
    exp_bits = e - 1 + 7;
    scaled = a / std::ldexp(1.0f, e - 1);  // in [1, 2)
  } else {
    exp_bits = 0;
    scaled = a / std::ldexp(1.0f, -6);  // in [0, 1): subnormal
  }
  float m = scaled * 8.0f;  // 3 mantissa bits
  // RNE: round m to nearest int, ties to even.
  float rf = std::floor(m);
  float frac = m - rf;
  int mi = (int)rf;
  if (frac > 0.5f) mi += 1;
  else if (frac == 0.5f) mi += (mi & 1);
  if (mi == 16) {  // mantissa overflow -> bump exponent
    if (exp_bits == 0) { exp_bits = 1; mi = 8; }
    else if (exp_bits == 15) return neg ? 0xf8 : 0x78;
    else { exp_bits += 1; mi = 8; }
    // re-check saturation at the new exponent
    if (exp_bits == 15 && mi == 16) return neg ? 0xf8 : 0x78;
  }
  if (exp_bits > 15) return neg ? 0xf8 : 0x78;
  return (uint8_t)((neg ? 0x80 : 0x00) | (exp_bits << 3) | mi);
}

// Legacy-cache store: ``mean`` (the bf16-rounded pooled vector) at cache
// slot [page, sip] -- fp8 K bytes then the fp32 scale. Mirrors the fp8
// epilogue layout (K region then trailing scales).
inline void ref_store_fp8(const std::vector<float>& mean, int head_dim,
                          int slots_per_page, std::vector<uint8_t>& cache_u8,
                          int page, int sip, bool round_scale) {
  const int page_bytes = slots_per_page * (head_dim + 4);
  uint8_t* k_dst = cache_u8.data() + (size_t)page * page_bytes
                 + (size_t)sip * head_dim;
  float* scale_dst = reinterpret_cast<float*>(
      cache_u8.data() + (size_t)page * page_bytes)
      + (slots_per_page * head_dim / 4) + sip;
  float amax = 0.0f;
  for (int d = 0; d < head_dim; ++d)
    amax = std::max(amax, std::fabs(mean[d]));
  const float y = round_scale ? std::exp2f(std::floor(std::log2f(amax / 448.0f)))
                              : amax / 448.0f;
  const float s_inv = (amax > 0.0f) ? 1.0f / y : 0.0f;
  for (int d = 0; d < head_dim; ++d) {
    const float q = mean[d] * s_inv;
    k_dst[d] = (amax > 0.0f) ? ref_f32_to_fp8e4m3fn(q) : 0;
  }
  std::memcpy(scale_dst, &y, 4);
}

}  // namespace dsa_kpool_ref

