    for (auto& x : chunk_k) x = rf();
    for (auto& x : chunk_score) x = rf();
    for (auto& x : tail_k) x = rf();
    for (auto& x : tail_score) x = rf();
    for (auto& x : ape) x = rf();
    std::vector<int32_t> req_pool_idx(c.n_pools), n_from_tail(c.n_pools),
