    for (int r = 0; r < c.n_pools; ++r) {
      req_pool_idx[r] = static_cast<int32_t>(rng() % c.n_reqs);
      n_from_tail[r] = static_cast<int32_t>(rng() % (c.pool_size + 1));  // [0, pool_size]
